with valid_store_sales as (select *, datediff(current_date(), sale_date) as days_since_sale_date from store_sales where units > 27 and store_id in (1, 2, 4, 5)), agg as (select store_id, round(stddev(days_since_sale_date), 2) as stddev_days_since_sale_date, round(avg(days_since_sale_date), 2) as avg_days_since_sale_date from valid_store_sales group by store_id) select store_id, avg_days_since_sale_date from agg;
